// async функция всегда возвращает промис
async function greet() {
  return "Hello!";  // автоматически оборачивается в Promise.resolve("Hello!")
}

// Вызов: возвращает промис
const result = greet();
console.log(result);  // Promise { "Hello!" }

// Чтобы получить значение — ждём в другой async
async function main() {
  const val = await greet();  // ждём промис → получаем "Hello!"
  console.log(val);  // Hello!
}
main();

async function fetchData() {
  return { users: 42 };  // автоматически: Promise.resolve({ users: 42 })
}

// Вызов: получаем промис
const promise = fetchData();
promise.then(data => console.log(data.users));  // 42

async function load() {
  const data = await Promise.resolve({ name: "Alice" });
  console.log(data.name);  // Alice — значение разворачено!

  // Без await пришлось бы:
  // Promise.resolve({ name: "Alice" }).then(data => { ... })
}
load();

async function loadUser(id) {
  try {
    const user = await fetchUser(id);  // может отклониться
    console.log(user.name);             // выполнится только если ok
  } catch (error) {
    console.error("Не удалось загрузить:", error.message);  // обработаем
  }
  console.log("Конец функции");  // выполнится всегда
}

