// БАГ: await вне async
// await Promise.resolve("ok");  // SyntaxError!

// ПРАВИЛЬНО: внутри async
async function main() {
  const val = await Promise.resolve("ok");
  console.log(val);
}

// ИЛИ: top-level await в ESM
// const val = await Promise.resolve("ok");  // работает в .mjs

async function fetchData() {
  return { name: "Alice" };
}

// БАГ: забыл await
async function wrong() {
  const data = fetchData();  // это Promise!
  console.log(data.name);  // undefined — у промиса нет name!
}

// ПРАВИЛЬНО: с await
async function right() {
  const data = await fetchData();  // это объект
  console.log(data.name);  // Alice
}

