// СЕРИАЛЬНО: ждём по очереди (медленно)
async function slow() {
  const a = await fetchA();  // 1 сек
  const b = await fetchB();  // 1 сек
  const c = await fetchC();  // 1 сек
  // Итого: 3 секунды
}

// ПАРАЛЛЕЛЬНО: запускаем вместе (быстро)
async function fast() {
  const [a, b, c] = await Promise.all([
    fetchA(),
    fetchB(),
    fetchC()
  ]);
  // Итого: 1 секунда — все три запроса одновременно!

async function getData() {
  // Нет await — но всё равно возвращает Promise
  return { data: "ready" };
}

// getData() === Promise.resolve({ data: "ready" })
console.log(typeof getData());  // "object" — это промис

const ids = [1, 2, 3];

// Последовательно: ждём каждый
for (const id of ids) {
  const user = await fetchUser(id);
  console.log(user.name);
}
// Итого: 3 секунды (3 запроса по 1 сек)

// Параллельно:
const users = await Promise.all(ids.map(id => fetchUser(id)));
users.forEach(u => console.log(u.name));
// Итого: 1 секунда

// Внутри async — try/catch
async function load() {
  try {
    const user = await fetchUser(1);
    console.log(user.name);
  } catch (err) {
    console.error("Ошибка:", err.message);
  }
}

// Снаружи async — .catch()
fetchUser(1)
  .then(user => console.log(user.name))
  .catch(err => console.error("Ошибка:", err.message));

